graphql-resolver-001.example:
```js
const resolvers = {
  Query: {
    // parent is the root value; args has { id }
    user: (parent, args, context, info) => context.db.user.findById(args.id),
  },
  User: {
    // parent is the User returned above
    posts: (user, args, context) => context.db.post.byAuthor(user.id),
  },
};
```

graphql-resolver-002.example:
```js
const resolvers = {
  Query: {
    // returns an object whose keys match User's fields
    user: () => ({ id: '1', name: 'Ada', email: 'ada@x.com' }),
  },
  // No User resolvers needed: defaults read user.id, user.name, user.email.
};
```

graphql-resolver-003.example:
