graphql-sub-002.example:
```js
import { createClient } from 'graphql-ws';

const client = createClient({ url: 'ws://localhost:4000/graphql' });

const unsubscribe = client.subscribe(
  { query: 'subscription { commentAdded(postId: "1") { id text } }' },
  {
    next: (data) => console.log('event', data),
    error: (err) => console.error(err),
    complete: () => console.log('done'),
  },
);
```

graphql-sub-003.example:
```js
const resolvers = {
  Mutation: {
    addComment: async (_p, { postId, text }, { pubsub, db }) => {
      const comment = await db.comment.create({ postId, text });
      pubsub.publish(`COMMENT_ADDED_${postId}`, { commentAdded: comment });
      return comment;
    },
  },
  Subscription: {
    commentAdded: {
      subscribe: (_p, { postId }, { pubsub }) =>
        pubsub.asyncIterator(`COMMENT_ADDED_${postId}`),
    },
  },
};
```
